const response = $input.first().json;
const input = $('Execute Workflow Trigger').first().json;

let carousel;
try {
  const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  carousel = JSON.parse(text);
} catch (e) {
  throw new Error('Erreur parsing carrousel: ' + e.message);
}

// Output each slide as separate item for batch processing
const slides = (carousel.slides || []).map(slide => ({
  ...slide,
  carousel_title: carousel.carousel_title,
  caption: carousel.caption,
  hashtags: carousel.hashtags,
  subject: input.subject,
  network: input.network || 'instagram'
}));

return slides.map(s => ({ json: s }));

const allSlides = $('Batch — Par slide').all();
const imageResults = $input.all();

const result = allSlides.map((slide, i) => ({
  slide_number: slide.json.slide_number,
  headline: slide.json.headline,
  body_text: slide.json.body_text,
  image_url: imageResults[i]?.json?.file_url || '',
  layout: slide.json.layout
}));

const firstSlide = allSlides[0]?.json || {};

return [{
  json: {
    carousel_title: firstSlide.carousel_title,
    slides: result,
    caption: firstSlide.caption,
    hashtags: firstSlide.hashtags,
    subject: firstSlide.subject,
    network: firstSlide.network,
    generated_at: new Date().toISOString()
  }
}];
